-- Categories are name + image. Description is removed.
-- image_url stays nullable so existing rows remain valid until an image is set.
-- New categories created through the API must send an image URL.

ALTER TABLE "categories" DROP COLUMN "description";

ALTER TABLE "categories" ADD COLUMN "image_url" TEXT;

CREATE TABLE "contact_messages" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" VARCHAR(120) NOT NULL,
    "phone" VARCHAR(30) NOT NULL,
    "email" VARCHAR(255) NOT NULL,
    "message" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "contact_messages_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "contact_messages_created_at_idx"
  ON "contact_messages"("created_at");
